    {
        ["ns.acc"] = new() { ["en"] = "Accessibility", ["es"] = "Accesibilidad", ["fr"] = "Accessibilité", ["de"] = "Barrierefreiheit", ["pt"] = "Acessibilidade", ["it"] = "Accessibilità", ["ja"] = "アクセシビリティ", ["zh"] = "无障碍", ["hi"] = "सुलभता", ["ar"] = "إمكانية الوصول" },
