        ["ns.acc.needs.title"] = new() { ["en"] = "Who is expected here", ["es"] = "A quién esperamos aquí", ["fr"] = "Qui est attendu ici", ["de"] = "Wer hier erwartet wird", ["pt"] = "Quem é esperado aqui", ["it"] = "Chi è atteso qui", ["ja"] = "ここに来ることが想定されている人", ["zh"] = "这里期待谁的到来", ["hi"] = "यहाँ किनकी अपेक्षा है", ["ar"] = "من ننتظر هنا" },
        ["ns.acc.needs.blind"] = new() { ["en"] = "Blind and low-vision: every function works by text, images carry descriptions, and the screens use standard controls a screen reader can walk.", ["es"] = "Personas ciegas o con baja visión: cada función opera por texto, las imágenes llevan descripciones y las pantallas usan controles estándar que un lector de pantalla puede recorrer.", ["fr"] = "Personnes aveugles ou malvoyantes : chaque fonction passe par le texte, les images portent des descriptions et les écrans utilisent des contrôles standard qu’un lecteur d’écran peut parcourir.", ["de"] = "Blinde und sehbehinderte Menschen: jede Funktion geht über Text, Bilder tragen Beschreibungen, und die Oberfläche nutzt Standard-Elemente, die ein Screenreader ablaufen kann.", ["pt"] = "Pessoas cegas ou com baixa visão: toda função opera por texto, as imagens têm descrições e as telas usam controles padrão que um leitor de tela consegue percorrer.", ["it"] = "Persone cieche o ipovedenti: ogni funzione passa dal testo, le immagini hanno descrizioni e le schermate usano controlli standard che uno screen reader può percorrere.", ["ja"] = "全盲・弱視の方：すべての機能はテキストで使え、画像には説明が付き、画面はスクリーンリーダーがたどれる標準コントロールでできています。", ["zh"] = "盲人和低视力者：一切功能都可通过文字完成，图像带有描述，界面使用屏幕阅读器可以遍历的标准控件。", ["hi"] = "दृष्टिहीन और कम दृष्टि वाले: हर कार्य पाठ से होता है, चित्रों के साथ विवरण है, और स्क्रीन में मानक नियंत्रण हैं जिन्हें स्क्रीन रीडर पढ़ सकता है।", ["ar"] = "المكفوفون وضعاف البصر: كل وظيفة تعمل بالنص، والصور تحمل أوصافًا، والشاشات تستخدم عناصر قياسية يستطيع قارئ الشاشة تتبعها." },
        ["ns.acc.needs.deaf"] = new() { ["en"] = "Deaf and hard of hearing: nothing here requires sound — voice is always optional, never the only way.", ["es"] = "Personas sordas o con pérdida auditiva: nada aquí requiere sonido; la voz es siempre opcional, nunca el único camino.", ["fr"] = "Personnes sourdes ou malentendantes : rien ici n’exige de son — la voix est toujours facultative, jamais le seul chemin.", ["de"] = "Gehörlose und schwerhörige Menschen: nichts hier verlangt Ton — Sprache ist immer optional, nie der einzige Weg.", ["pt"] = "Pessoas surdas ou com perda auditiva: nada aqui exige som — a voz é sempre opcional, nunca o único caminho.", ["it"] = "Persone sorde o con perdita d’udito: niente qui richiede l’audio — la voce è sempre facoltativa, mai l’unica via.", ["ja"] = "ろう・難聴の方：ここでは音を必要とするものはありません。音声は常に任意で、唯一の手段になることはありません。", ["zh"] = "聋人和听障者：这里没有任何功能依赖声音——语音永远是可选的，绝不是唯一途径。", ["hi"] = "बधिर और कम सुनने वाले: यहाँ किसी चीज़ के लिए ध्वनि आवश्यक नहीं — आवाज़ हमेशा वैकल्पिक है, कभी एकमात्र रास्ता नहीं।", ["ar"] = "الصم وضعاف السمع: لا شيء هنا يتطلب صوتًا — الصوت اختياري دائمًا، وليس الطريق الوحيد أبدًا." },
