        ["cu.reseal"] = new() { ["en"] = "Reseal under the active key", ["es"] = "Volver a sellar con la clave activa", ["fr"] = "Resceller avec la clé active", ["de"] = "Mit dem aktiven Schlüssel neu versiegeln", ["pt"] = "Voltar a selar com a chave ativa", ["it"] = "Risigillare con la chiave attiva", ["ja"] = "有効な鍵で封印し直す", ["zh"] = "用当前密钥重新封存", ["hi"] = "सक्रिय कुंजी से फिर सील करें", ["ar"] = "إعادة الختم بالمفتاح النشط" },
        ["cu.reseal.note"] = new() { ["en"] = "A reseal skips every record the customer holds the key for, and reports how many. That number is the honest measure of bring-your-own-key: it is how much of the vault the operator could not touch even when asked to.", ["es"] = "Un resellado omite cada registro cuya clave tiene el cliente, e informa cuántos son. Esa cifra es la medida honesta de traer tu propia clave: es cuánto de la cámara el operador no pudo tocar ni cuando se lo pidieron.", ["fr"] = "Un rescellement saute chaque enregistrement dont le client détient la clé, et indique combien. Ce nombre est la mesure honnête d'apporter sa propre clé : c'est la part du coffre que l'opérateur n'a pas pu toucher, même sur demande.", ["de"] = "Ein Neuversiegeln überspringt jeden Datensatz, dessen Schlüssel der Kunde hält, und meldet wie viele. Diese Zahl ist das ehrliche Maß für den eigenen Schlüssel: sie sagt, wie viel des Tresors der Betreiber nicht anrühren konnte, selbst auf Aufforderung.", ["pt"] = "Voltar a selar salta todos os registos cuja chave o cliente detém, e diz quantos. Esse número é a medida honesta de trazer a própria chave: é quanto do cofre o operador não conseguiu tocar, mesmo quando lho pediram.", ["it"] = "Risigillare salta ogni record di cui il cliente detiene la chiave, e riporta quanti. Quel numero è la misura onesta della chiave propria: è quanta parte della cassaforte l'operatore non ha potuto toccare, nemmeno su richiesta.", ["ja"] = "封印し直す処理は、顧客が鍵を持つレコードをすべて飛ばし、その件数を報告します。この数字こそが「自分の鍵を持ち込む」ことの正直な指標です。求められてもなお運営者が触れられなかった量を示します。", ["zh"] = "重新封存会跳过每一条由客户掌管密钥的记录，并报告跳过了多少条。这个数字才是「自带密钥」的诚实度量：它说明即便被要求，运营方也有多少内容无法触及。", ["hi"] = "पुनः सील करना हर उस रिकॉर्ड को छोड़ देता है जिसकी कुंजी ग्राहक के पास है, और बताता है कि कितने छोड़े गए। वही संख्या अपनी कुंजी लाने का ईमानदार माप है: यह बताती है कि माँगे जाने पर भी संचालक तिजोरी का कितना हिस्सा छू नहीं सका।", ["ar"] = "تتخطّى إعادة الختم كل سجلّ يحتفظ العميل بمفتاحه، وتُبلغ بعددها. هذا الرقم هو القياس الصادق لإحضار مفتاحك: إنه مقدار ما لم يستطع المشغّل لمسه من الخزنة حتى حين طُلب منه ذلك." },
