        ["cu.deploy"] = new() { ["en"] = "Record a deployment", ["es"] = "Registrar un despliegue", ["fr"] = "Enregistrer un déploiement", ["de"] = "Eine Installation festhalten", ["pt"] = "Registar uma instalação", ["it"] = "Registrare un'installazione", ["ja"] = "配備を記録する", ["zh"] = "记录一次部署", ["hi"] = "एक परिनियोजन दर्ज करें", ["ar"] = "تسجيل عملية نشر" },
