        ["op.none"] = new() { ["en"] = "Nothing yet. When QRME's departments coordinate with the tandem configured, each joint plan seals into this vault and appears here.", ["es"] = "Nada todavía. Cuando los departamentos de QRME se coordinen con el tándem configurado, cada plan conjunto se sella en esta bóveda y aparece aquí.", ["fr"] = "Rien pour l'instant. Lorsque les services de QRME se coordonnent avec le tandem configuré, chaque plan commun est scellé dans ce coffre et apparaît ici.", ["de"] = "Noch nichts. Sobald die Abteilungen von QRME sich mit eingerichtetem Tandem abstimmen, wird jeder gemeinsame Plan in diesen Tresor versiegelt und erscheint hier.", ["pt"] = "Ainda nada. Quando os departamentos do QRME se coordenarem com o tandem configurado, cada plano conjunto é selado neste cofre e aparece aqui.", ["it"] = "Ancora nulla. Quando i reparti di QRME si coordinano con il tandem configurato, ogni piano congiunto viene sigillato in questa cassaforte e compare qui.", ["ja"] = "まだ何もありません。QRME の各部門がタンデムを設定して連携すると、共同計画はこの保管庫に封印され、ここに現れます。", ["zh"] = "暂无内容。当 QRME 的各部门在配置了串联后进行协调时，每份联合计划都会封存入此保险库并显示在这里。", ["hi"] = "अभी कुछ नहीं। जब QRME के विभाग कॉन्फ़िगर किए गए टैंडेम के साथ समन्वय करते हैं, तो हर संयुक्त योजना इस वॉल्ट में सील होकर यहाँ दिखती है।", ["ar"] = "لا شيء بعد. حين تنسّق أقسام QRME مع الترادف مضبوطًا، تُختَم كل خطة مشتركة في هذه الخزنة وتظهر هنا." },
        ["op.events"] = new() { ["en"] = "audited event(s) · chain", ["es"] = "evento(s) auditado(s) · cadena", ["fr"] = "événement(s) audité(s) · chaîne", ["de"] = "geprüfte(s) Ereignis(se) · Kette", ["pt"] = "evento(s) auditado(s) · cadeia", ["it"] = "evento/i verificato/i · catena", ["ja"] = "件の監査済みイベント · チェーン", ["zh"] = "个已审计事件 · 链", ["hi"] = "ऑडिट की गई घटना(एँ) · श्रृंखला", ["ar"] = "حدث/أحداث مدقَّقة · سلسلة" },
        ["au.actions"] = new() { ["en"] = "recorded actions · retention", ["es"] = "acciones registradas · conservación", ["fr"] = "actions consignées · conservation", ["de"] = "festgehaltene Aktionen · Aufbewahrung", ["pt"] = "ações registadas · retenção", ["it"] = "azioni registrate · conservazione", ["ja"] = "記録された操作 · 保持", ["zh"] = "已记录的操作 · 保留", ["hi"] = "दर्ज की गई क्रियाएँ · प्रतिधारण", ["ar"] = "إجراءات مسجَّلة · احتفاظ" },
        ["ov.health"] = new() { ["en"] = "Backend health", ["es"] = "Salud del backend", ["fr"] = "Santé du backend", ["de"] = "Backend-Zustand", ["pt"] = "Saúde do backend", ["it"] = "Stato del backend", ["ja"] = "バックエンドの状態", ["zh"] = "后端健康状态", ["hi"] = "बैकएंड स्थिति", ["ar"] = "حالة الخادم الخلفي" },
        ["co.bequests"] = new() { ["en"] = "Bequests", ["es"] = "Legados", ["fr"] = "Legs", ["de"] = "Vermächtnisse", ["pt"] = "Legados", ["it"] = "Lasciti", ["ja"] = "遺贈", ["zh"] = "遗赠", ["hi"] = "वसीयतें", ["ar"] = "الوصايا" },
        ["co.bequests.note"] = new() { ["en"] = "A standing instruction, dormant when written. Creating one grants nothing — it records what would become readable, by whom, if the condition were ever attested by an operator holding a different credential.", ["es"] = "Una instrucción permanente, latente en el momento de escribirla. Crearla no concede nada: deja constancia de qué pasaría a ser legible, y por quién, si algún día un operador con otra credencial diera fe de la condición.", ["fr"] = "Une instruction permanente, dormante à l'écriture. En créer une n'accorde rien : elle consigne ce qui deviendrait lisible, et par qui, si la condition était un jour attestée par un opérateur détenant un autre identifiant.", ["de"] = "Eine dauerhafte Anweisung, beim Verfassen ruhend. Sie zu erstellen gewährt nichts — sie hält fest, was lesbar würde und für wen, falls die Bedingung je von einem Betreiber mit anderem Berechtigungsnachweis bezeugt würde.", ["pt"] = "Uma instrução permanente, adormecida quando é escrita. Criá-la não concede nada — regista o que passaria a ser legível, e por quem, se a condição alguma vez fosse atestada por um operador com outra credencial.", ["it"] = "Un'istruzione permanente, dormiente quando viene scritta. Crearla non concede nulla: registra cosa diventerebbe leggibile, e da chi, se la condizione fosse mai attestata da un operatore con una credenziale diversa.", ["ja"] = "書いた時点では休眠している常設の指示です。作成しても何も付与されません。別の資格情報を持つ運営者がその条件を証明した場合に、何が誰にとって読めるようになるかを記録するだけです。", ["zh"] = "一条长期指令，写下时处于休眠状态。创建它并不授予任何权限——它记录的是：若将来由持有另一份凭据的运营方证实了该条件，什么会变得可读、由谁可读。", ["hi"] = "एक स्थायी निर्देश, लिखे जाने के समय निष्क्रिय। इसे बनाने से कुछ भी प्रदान नहीं होता — यह दर्ज करता है कि यदि कभी किसी भिन्न प्रमाण-पत्र वाले संचालक ने शर्त प्रमाणित की, तो क्या और किसके लिए पठनीय हो जाएगा।", ["ar"] = "تعليمة دائمة، خاملة وقت كتابتها. إنشاؤها لا يمنح شيئًا — بل يسجّل ما الذي سيصبح مقروءًا، ولمن، لو شهد بتحقّق الشرط يومًا مشغّلٌ يحمل اعتمادًا مختلفًا." },
        ["co.nothing"] = new() { ["en"] = "Nothing bequeathed.", ["es"] = "Nada legado.", ["fr"] = "Rien de légué.", ["de"] = "Nichts vermacht.", ["pt"] = "Nada legado.", ["it"] = "Nessun lascito.", ["ja"] = "遺贈はありません。", ["zh"] = "尚无遗赠。", ["hi"] = "कुछ वसीयत नहीं किया गया।", ["ar"] = "لا وصايا." },
