        ["co.revoke"] = new() { ["en"] = "Revoke", ["es"] = "Revocar", ["fr"] = "Révoquer", ["de"] = "Widerrufen", ["pt"] = "Revogar", ["it"] = "Revocare", ["ja"] = "取り消す", ["zh"] = "撤销", ["hi"] = "निरस्त करें", ["ar"] = "إبطال" },
        ["co.grantee.ph"] = new() { ["en"] = "Who inherits the read", ["es"] = "Quién hereda la lectura", ["fr"] = "Qui hérite de la lecture", ["de"] = "Wer das Leserecht erbt", ["pt"] = "Quem herda a leitura", ["it"] = "Chi eredita la lettura", ["ja"] = "読む権利を継ぐ人", ["zh"] = "由谁继承读取权", ["hi"] = "पठन का उत्तराधिकारी कौन", ["ar"] = "من يرث حق القراءة" },
        ["co.prefixes.ph"] = new() { ["en"] = "Key prefixes, comma separated", ["es"] = "Prefijos de clave, separados por comas", ["fr"] = "Préfixes de clé, séparés par des virgules", ["de"] = "Schlüsselpräfixe, durch Komma getrennt", ["pt"] = "Prefixos de chave, separados por vírgulas", ["it"] = "Prefissi di chiave, separati da virgole", ["ja"] = "キーの接頭辞（カンマ区切り）", ["zh"] = "键前缀，用逗号分隔", ["hi"] = "कुंजी उपसर्ग, अल्पविराम से अलग", ["ar"] = "بادئات المفاتيح، مفصولة بفواصل" },
        ["co.note.ph"] = new() { ["en"] = "Note (optional)", ["es"] = "Nota (opcional)", ["fr"] = "Note (facultative)", ["de"] = "Notiz (optional)", ["pt"] = "Nota (opcional)", ["it"] = "Nota (facoltativa)", ["ja"] = "メモ（任意）", ["zh"] = "备注（可选）", ["hi"] = "टिप्पणी (वैकल्पिक)", ["ar"] = "ملاحظة (اختيارية)" },
        ["co.record"] = new() { ["en"] = "Record a bequest", ["es"] = "Registrar un legado", ["fr"] = "Enregistrer un legs", ["de"] = "Ein Vermächtnis festhalten", ["pt"] = "Registar um legado", ["it"] = "Registrare un lascito", ["ja"] = "遺贈を記録する", ["zh"] = "记录一份遗赠", ["hi"] = "एक वसीयत दर्ज करें", ["ar"] = "تسجيل وصية" },
        ["co.activation"] = new() { ["en"] = "Activation — the operator's act", ["es"] = "Activación — el acto del operador", ["fr"] = "Activation — l'acte de l'opérateur", ["de"] = "Aktivierung — die Handlung des Betreibers", ["pt"] = "Ativação — o ato do operador", ["it"] = "Attivazione — l'atto dell'operatore", ["ja"] = "発動 — 運営者の行為", ["zh"] = "启用——运营方的行为", ["hi"] = "सक्रियण — संचालक का कार्य", ["ar"] = "التفعيل — فِعل المشغّل" },
        ["co.activation.note"] = new() { ["en"] = "Activation needs an admin token, not this tenant's. That separation is the point: the person who wrote the bequest cannot also be the one who declares its condition met. The reference given here goes into the audit chain, and the grant token is shown once.", ["es"] = "La activación requiere un token de administrador, no el de este inquilino. Esa separación es el objetivo: quien escribió el legado no puede ser también quien declare cumplida su condición. La referencia dada aquí entra en la cadena de auditoría, y el token de concesión se muestra una sola vez.", ["fr"] = "L'activation exige un jeton d'administration, pas celui de ce locataire. Cette séparation est le but : la personne qui a rédigé le legs ne peut pas être aussi celle qui déclare sa condition remplie. La référence donnée ici entre dans la chaîne d'audit, et le jeton d'octroi n'est affiché qu'une fois.", ["de"] = "Die Aktivierung verlangt ein Admin-Token, nicht das dieses Mandanten. Genau diese Trennung ist der Zweck: wer das Vermächtnis verfasst hat, kann nicht zugleich dessen Bedingung für erfüllt erklären. Der hier angegebene Beleg geht in die Prüfkette, und das Gewährungs-Token wird einmal angezeigt.", ["pt"] = "A ativação exige um token de administração, não o deste inquilino. Essa separação é o objetivo: quem escreveu o legado não pode ser também quem declara cumprida a sua condição. A referência aqui dada entra na cadeia de auditoria, e o token de concessão é mostrado uma só vez.", ["it"] = "L'attivazione richiede un token di amministrazione, non quello di questo tenant. Quella separazione è il punto: chi ha scritto il lascito non può essere anche chi ne dichiara soddisfatta la condizione. Il riferimento indicato qui entra nella catena di audit, e il token di concessione è mostrato una sola volta.", ["ja"] = "発動にはこのテナントのものではなく管理者トークンが必要です。その分離こそが要点で、遺贈を書いた本人がその条件の成立を宣言する者を兼ねることはできません。ここで示す典拠は監査の連鎖に入り、付与トークンは一度だけ表示されます。", ["zh"] = "启用需要管理员令牌，而不是该租户的令牌。这一分离正是要点：写下遗赠的人不能同时是宣告其条件已成立的人。此处填写的凭据会进入审计链，而授予令牌只显示一次。", ["hi"] = "सक्रियण के लिए इस टेनेंट का नहीं, बल्कि व्यवस्थापक टोकन चाहिए। यही पृथक्करण मूल बात है: जिसने वसीयत लिखी, वही उसकी शर्त पूरी होने की घोषणा नहीं कर सकता। यहाँ दिया गया संदर्भ ऑडिट शृंखला में जाता है, और अनुदान टोकन एक ही बार दिखाया जाता है।", ["ar"] = "يحتاج التفعيل إلى رمز إداري، لا إلى رمز هذا المستأجر. هذا الفصل هو المقصود: من كتب الوصية لا يصح أن يكون هو نفسه من يعلن تحقّق شرطها. والمرجع المُدخل هنا يدخل سلسلة التدقيق، ويُعرض رمز المنح مرة واحدة." },
        ["co.admin.ph"] = new() { ["en"] = "Admin token", ["es"] = "Token de administrador", ["fr"] = "Jeton d'administration", ["de"] = "Admin-Token", ["pt"] = "Token de administrador", ["it"] = "Token di amministrazione", ["ja"] = "管理者トークン", ["zh"] = "管理员令牌", ["hi"] = "एडमिन टोकन", ["ar"] = "رمز المشرف" },
        ["co.ref.ph"] = new() { ["en"] = "What attests the condition", ["es"] = "Qué da fe de la condición", ["fr"] = "Ce qui atteste la condition", ["de"] = "Was die Bedingung bezeugt", ["pt"] = "O que atesta a condição", ["it"] = "Cosa attesta la condizione", ["ja"] = "条件を証明するもの", ["zh"] = "以何证实该条件", ["hi"] = "शर्त को क्या प्रमाणित करता है", ["ar"] = "ما الذي يشهد بالشرط" },
        ["co.activate"] = new() { ["en"] = "Activate", ["es"] = "Activar", ["fr"] = "Activer", ["de"] = "Aktivieren", ["pt"] = "Ativar", ["it"] = "Attivare", ["ja"] = "発動する", ["zh"] = "启用", ["hi"] = "सक्रिय करें", ["ar"] = "تفعيل" },
        ["co.minted"] = new() { ["en"] = "Grant token — copy it now.", ["es"] = "Token de concesión — cópialo ahora.", ["fr"] = "Jeton d'octroi — copiez-le maintenant.", ["de"] = "Gewährungs-Token — jetzt kopieren.", ["pt"] = "Token de concessão — copie-o agora.", ["it"] = "Token di concessione — copialo ora.", ["ja"] = "付与トークン — いま控えてください。", ["zh"] = "授予令牌——请立即复制。", ["hi"] = "अनुदान टोकन — अभी कॉपी करें।", ["ar"] = "رمز المنح — انسخه الآن." },
        ["co.minted.note"] = new() { ["en"] = "It is not stored and will not be shown again.", ["es"] = "No se guarda y no volverá a mostrarse.", ["fr"] = "Il n'est pas conservé et ne sera plus affiché.", ["de"] = "Es wird nicht gespeichert und nicht erneut angezeigt.", ["pt"] = "Não é guardado e não voltará a ser mostrado.", ["it"] = "Non viene conservato e non sarà mostrato di nuovo.", ["ja"] = "保存されず、再表示されることはありません。", ["zh"] = "它不会被保存，也不会再次显示。", ["hi"] = "यह संग्रहीत नहीं होता और दोबारा नहीं दिखाया जाएगा।", ["ar"] = "لا يُخزَّن ولن يُعرض مرة أخرى." },
        ["co.revoke.grant"] = new() { ["en"] = "Revoke the grant token", ["es"] = "Revocar el token de concesión", ["fr"] = "Révoquer le jeton d'octroi", ["de"] = "Das Gewährungs-Token widerrufen", ["pt"] = "Revogar o token de concessão", ["it"] = "Revocare il token di concessione", ["ja"] = "付与トークンを取り消す", ["zh"] = "撤销授予令牌", ["hi"] = "अनुदान टोकन रद्द करें", ["ar"] = "إبطال رمز المنح" },
        ["co.redeem"] = new() { ["en"] = "Redeeming — the heir's side", ["es"] = "Canje — el lado del heredero", ["fr"] = "Le rachat — du côté de l'héritier", ["de"] = "Einlösen — die Seite der erbenden Person", ["pt"] = "Resgate — o lado do herdeiro", ["it"] = "Riscatto — il lato dell'erede", ["ja"] = "行使 — 相続する側", ["zh"] = "兑现——继承人这一侧", ["hi"] = "भुनाना — उत्तराधिकारी का पक्ष", ["ar"] = "الاستيفاء — جانب الوارث" },
        ["co.redeem.note"] = new() { ["en"] = "Two separate secrets, and neither works alone: the grant token says the condition was attested, the customer key decrypts. An executor who holds only the token opens nothing.", ["es"] = "Dos secretos distintos, y ninguno sirve por sí solo: el token de concesión dice que la condición fue atestiguada, la clave del cliente descifra. Un albacea que solo tenga el token no abre nada.", ["fr"] = "Deux secrets distincts, et aucun ne suffit seul : le jeton d'octroi dit que la condition a été attestée, la clé du client déchiffre. Un exécuteur qui ne détient que le jeton n'ouvre rien.", ["de"] = "Zwei getrennte Geheimnisse, und keines wirkt allein: das Gewährungs-Token bezeugt die Bedingung, der Kundenschlüssel entschlüsselt. Wer nur das Token hält, öffnet nichts.", ["pt"] = "Dois segredos distintos, e nenhum funciona sozinho: o token de concessão diz que a condição foi atestada, a chave do cliente decifra. Um testamenteiro que tenha apenas o token não abre nada.", ["it"] = "Due segreti distinti, e nessuno funziona da solo: il token di concessione dice che la condizione è stata attestata, la chiave del cliente decifra. Un esecutore che possiede solo il token non apre nulla.", ["ja"] = "別々の秘密が二つあり、どちらも単独では働きません。付与トークンは条件が証明されたことを示し、顧客鍵が復号します。トークンだけを持つ遺言執行者には何も開けません。", ["zh"] = "两份彼此独立的秘密，缺一不可：授予令牌表明条件已获证实，客户密钥负责解密。只持有令牌的遗嘱执行人什么也打不开。", ["hi"] = "दो अलग-अलग रहस्य, और कोई भी अकेले काम नहीं करता: अनुदान टोकन कहता है कि शर्त प्रमाणित हुई, ग्राहक कुंजी डिक्रिप्ट करती है। जिस निष्पादक के पास केवल टोकन है, वह कुछ नहीं खोल पाता।", ["ar"] = "سرّان منفصلان، ولا يكفي أيّهما وحده: رمز المنح يقول إن الشرط قد شُهد به، ومفتاح العميل يفكّ التشفير. ومنفّذ الوصية الذي يملك الرمز وحده لا يفتح شيئًا." },
        ["co.grant.ph"] = new() { ["en"] = "Grant token", ["es"] = "Token de concesión", ["fr"] = "Jeton d'octroi", ["de"] = "Gewährungs-Token", ["pt"] = "Token de concessão", ["it"] = "Token di concessione", ["ja"] = "付与トークン", ["zh"] = "授予令牌", ["hi"] = "अनुदान टोकन", ["ar"] = "رمز المنح" },
