        ["bri.ref.ph"] = new() { ["en"] = "a reference to withdraw by", ["es"] = "una referencia para retirarlo luego", ["fr"] = "une référence pour le retirer", ["de"] = "eine Referenz zum späteren Zurückziehen", ["pt"] = "uma referência para retirar depois", ["it"] = "un riferimento per ritirarlo", ["ja"] = "後で取り下げるための参照名", ["zh"] = "用于日后撤回的引用", ["hi"] = "बाद में वापस लेने के लिए एक संदर्भ", ["ar"] = "مرجع للسحب لاحقًا" },
