        ["bri.withdraw"] = new() { ["en"] = "Withdraw by reference", ["es"] = "Retirar por referencia", ["fr"] = "Retirer par référence", ["de"] = "Nach Referenz zurückziehen", ["pt"] = "Retirar por referência", ["it"] = "Ritirare per riferimento", ["ja"] = "参照名で取り下げる", ["zh"] = "按引用撤回", ["hi"] = "संदर्भ से वापस लें", ["ar"] = "السحب بالمرجع" },
        ["bri.sealed"] = new() { ["en"] = "Sealed as {key}", ["es"] = "Sellado como {key}", ["fr"] = "Scellé sous {key}", ["de"] = "Versiegelt als {key}", ["pt"] = "Selado como {key}", ["it"] = "Sigillato come {key}", ["ja"] = "{key} として封印しました", ["zh"] = "已封存为 {key}", ["hi"] = "{key} के रूप में सील", ["ar"] = "مختوم باسم {key}" },
        ["bri.held"] = new() { ["en"] = "{n} held. The listing is a count and a set of keys — never contents. A vault holding a thing is not the same as a vault showing it to whoever asks for the list.", ["es"] = "{n} en custodia. El listado es un recuento y un conjunto de claves, nunca contenidos. Que una bóveda guarde algo no es lo mismo que una bóveda se lo muestre a quien pida la lista.", ["fr"] = "{n} conservés. La liste est un compte et un ensemble de clés — jamais un contenu. Qu’un coffre détienne une chose n’est pas la même chose qu’un coffre qui la montre à quiconque demande la liste.", ["de"] = "{n} verwahrt. Die Auflistung ist eine Zahl und eine Menge von Schlüsseln — niemals Inhalte. Dass ein Tresor etwas hält, ist nicht dasselbe, wie dass er es jedem zeigt, der die Liste anfordert.", ["pt"] = "{n} em custódia. A listagem é uma contagem e um conjunto de chaves — nunca conteúdos. Um cofre guardar uma coisa não é o mesmo que um cofre mostrá-la a quem pedir a lista.", ["it"] = "{n} in custodia. L’elenco è un conteggio e un insieme di chiavi — mai contenuti. Che un caveau custodisca una cosa non equivale a un caveau che la mostra a chiunque chieda l’elenco.", ["ja"] = "保持数は {n} 件。一覧は件数と鍵の集合であり、中身では決してありません。保管庫が何かを保持していることと、一覧を求めた者にそれを見せることは別のことです。", ["zh"] = "持有 {n} 条。列表是一个计数和一组密钥 — 从不是内容。保险库持有某物，并不等于它会把该物展示给任何索取列表的人。", ["hi"] = "{n} रखे गए। सूची एक गिनती और कुंजियों का समुच्चय है — कभी सामग्री नहीं। वॉल्ट का किसी चीज़ को रखना और सूची माँगने वाले किसी को भी उसे दिखाना, एक बात नहीं है।", ["ar"] = "{n} محفوظة. القائمة عدد ومجموعة مفاتيح — لا محتويات أبدًا. أن تحفظ الخزنة شيئًا ليس كأن تعرضه على كل من يطلب القائمة." },
