        ["nadm.req.more"] = new() { ["en"] = "Rotation re-seals every record; retire deletes non-active versions (safe only after a reseal).", ["es"] = "La rotación vuelve a sellar todos los registros; retirar elimina las versiones no activas (seguro solo tras un resellado).", ["fr"] = "La rotation rescelle chaque enregistrement ; le retrait supprime les versions non actives (sûr seulement après un rescellement).", ["de"] = "Die Rotation versiegelt jeden Datensatz neu; das Zurückziehen löscht nicht aktive Versionen (nur nach einer Neuversiegelung sicher).", ["pt"] = "A rotação volta a selar todos os registos; retirar apaga as versões não ativas (seguro apenas após um novo selo).", ["it"] = "La rotazione risigilla ogni record; il ritiro elimina le versioni non attive (sicuro solo dopo una nuova sigillatura).", ["ja"] = "ローテーションはすべてのレコードを再封印します。廃止は非アクティブなバージョンを削除します（再封印後のみ安全）。", ["zh"] = "轮换会重新封存所有记录；停用会删除非活动版本（仅在重新封存后才安全）。", ["hi"] = "घुमाने से हर रिकॉर्ड फिर से सील होता है; हटाने से निष्क्रिय संस्करण मिटते हैं (केवल पुनः सील के बाद सुरक्षित)।", ["ar"] = "التدوير يعيد ختم كل سجل؛ والسحب يحذف الإصدارات غير النشطة (آمن فقط بعد إعادة الختم)." },
