        ["naud.desc"] = new() { ["en"] = "Every vault action is hash-chained. Verify recomputes the whole chain.", ["es"] = "Cada acción de la bóveda se encadena por hash. Verificar recalcula toda la cadena.", ["fr"] = "Chaque action du coffre est chaînée par hachage. Vérifier recalcule toute la chaîne.", ["de"] = "Jede Tresor-Aktion wird hash-verkettet. Die Prüfung berechnet die gesamte Kette neu.", ["pt"] = "Cada ação do cofre é encadeada por hash. Verificar recalcula toda a cadeia.", ["it"] = "Ogni azione della cassaforte è concatenata con hash. La verifica ricalcola l'intera catena.", ["ja"] = "保管庫のすべての操作はハッシュ連鎖されます。検証は連鎖全体を再計算します。", ["zh"] = "保险库的每次操作都以哈希连成链。验证会重算整条链。", ["hi"] = "वॉल्ट की हर कार्रवाई हैश-श्रृंखला में जुड़ती है। सत्यापन पूरी श्रृंखला की पुनर्गणना करता है।", ["ar"] = "كل إجراء في الخزنة يُسلسل بالتجزئة. والتحقق يعيد حساب السلسلة كاملة." },
