        ["nrob.sub"] = new() { ["en"] = "What your robots see stays sealed — every intake is encrypted at rest and hash-chained in the audit log.", ["es"] = "Lo que ven tus robots queda sellado: cada entrada se cifra en reposo y se encadena por hash en el registro de auditoría.", ["fr"] = "Ce que voient vos robots reste scellé — chaque entrée est chiffrée au repos et chaînée par hachage dans le journal d'audit.", ["de"] = "Was deine Roboter sehen, bleibt versiegelt — jede Aufnahme wird im Ruhezustand verschlüsselt und im Audit-Log hash-verkettet.", ["pt"] = "O que os seus robôs veem fica selado — cada entrada é cifrada em repouso e encadeada por hash no registo de auditoria.", ["it"] = "Ciò che vedono i tuoi robot resta sigillato — ogni acquisizione è cifrata a riposo e concatenata con hash nel registro di audit.", ["ja"] = "ロボットが見たものは封印されたままです — すべての取り込みは保存時に暗号化され、監査ログにハッシュ連鎖で記録されます。", ["zh"] = "你的机器人所见都被封存 — 每次采集都在静态加密，并以哈希链记入审计日志。", ["hi"] = "आपके रोबोट जो देखते हैं वह सील रहता है — हर इनटेक विश्राम में एन्क्रिप्ट होता है और ऑडिट लॉग में हैश-श्रृंखला से जुड़ता है।", ["ar"] = "ما تراه روبوتاتك يبقى مختومًا — كل التقاط يُشفَّر أثناء التخزين ويُسلسل بالتجزئة في سجل التدقيق." },
